-- Ent SQLite single-organization v10 snapshot with reviewed foreign keys.
CREATE TABLE `audit_logs` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `actor_id` integer NOT NULL, `operation` text NOT NULL, `resource` text NOT NULL, `resource_id` integer NULL, `request_id` text NULL, `module` text NOT NULL DEFAULT (''), `description` text NOT NULL DEFAULT (''), `method` text NOT NULL DEFAULT (''), `path` text NOT NULL DEFAULT (''), `ip` text NOT NULL DEFAULT (''), `user_agent` text NOT NULL DEFAULT (''), `browser` text NOT NULL DEFAULT (''), `os` text NOT NULL DEFAULT (''), `request_body` text NULL, `duration_ms` integer NOT NULL DEFAULT (0), `response_code` integer NOT NULL DEFAULT (200), `created_at` datetime NOT NULL);
CREATE INDEX `auditlog_created_at` ON `audit_logs` (`created_at`);
CREATE TABLE `captchas` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `public_id` text NOT NULL, `answer_hash` text NOT NULL, `expires_at` datetime NOT NULL, `used_at` datetime NULL, `created_at` datetime NOT NULL);
CREATE UNIQUE INDEX `captchas_public_id_key` ON `captchas` (`public_id`);
CREATE TABLE `departments` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `parent_id` integer NOT NULL DEFAULT (0), `name` text NOT NULL, `code` text NOT NULL, `category` text NOT NULL DEFAULT ('department'), `leader_id` integer NULL, `phone` text NULL, `email` text NULL, `sort` integer NOT NULL DEFAULT (0), `status` text NOT NULL DEFAULT ('enabled'), `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, CONSTRAINT `departments_leader_id_fk` FOREIGN KEY (`leader_id`) REFERENCES `users` (`id`) ON DELETE SET NULL);
CREATE UNIQUE INDEX `department_code` ON `departments` (`code`);
CREATE TABLE `dicts` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `code` text NOT NULL, `description` text NULL, `status` text NOT NULL DEFAULT ('enabled'), `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `dict_code` ON `dicts` (`code`);
CREATE TABLE `dict_items` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `dict_id` integer NOT NULL, `parent_id` integer NULL, `label` text NOT NULL, `value` text NOT NULL, `color` text NULL, `sort` integer NOT NULL DEFAULT (0), `status` text NOT NULL DEFAULT ('enabled'), `remark` text NULL, `metadata` json NULL, `created_by` integer NULL, `updated_by` integer NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, CONSTRAINT `dict_items_dict_id_fk` FOREIGN KEY (`dict_id`) REFERENCES `dicts` (`id`) ON DELETE CASCADE, CONSTRAINT `dict_items_parent_id_fk` FOREIGN KEY (`parent_id`) REFERENCES `dict_items` (`id`) ON DELETE SET NULL);
CREATE UNIQUE INDEX `dictitem_dict_id_value` ON `dict_items` (`dict_id`, `value`);
CREATE TABLE `file_storage_configs` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `provider` text NOT NULL DEFAULT ('local'), `status` text NOT NULL DEFAULT ('enabled'), `is_default` bool NOT NULL DEFAULT (false), `local_root_path` text NOT NULL, `remark` text NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL);
CREATE TABLE `login_attempts` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `key` text NOT NULL, `username_hash` text NOT NULL DEFAULT (''), `failures` integer NOT NULL DEFAULT (0), `locked_until` datetime NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `login_attempts_key_key` ON `login_attempts` (`key`);
CREATE TABLE `login_logs` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NULL, `username` text NOT NULL, `ip` text NULL, `event_type` text NOT NULL DEFAULT ('login'), `user_agent` text NOT NULL DEFAULT (''), `browser` text NOT NULL DEFAULT (''), `os` text NOT NULL DEFAULT (''), `success` bool NOT NULL, `reason` text NULL, `created_at` datetime NOT NULL);
CREATE INDEX `loginlog_created_at` ON `login_logs` (`created_at`);
CREATE TABLE `managed_files` (`id` uuid NOT NULL, `storage_config_id` integer NOT NULL, `uploader_id` integer NOT NULL, `original_name` text NOT NULL, `object_key` text NOT NULL, `size` integer NOT NULL, `mime_type` text NULL, `extension` text NULL, `visibility` text NOT NULL DEFAULT ('public'), `content_hash` text NULL, `delete_pending` bool NOT NULL DEFAULT (false), `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `managed_files_storage_config_id_fk` FOREIGN KEY (`storage_config_id`) REFERENCES `file_storage_configs` (`id`) ON DELETE RESTRICT, CONSTRAINT `managed_files_uploader_id_fk` FOREIGN KEY (`uploader_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT);
CREATE INDEX `managedfile_created_at` ON `managed_files` (`created_at`);
CREATE INDEX `managedfile_storage_config_id` ON `managed_files` (`storage_config_id`);
CREATE TABLE `menus` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `parent_id` integer NOT NULL DEFAULT (0), `title` text NOT NULL, `name` text NULL, `path` text NULL, `component` text NULL, `icon` text NULL, `type` text NOT NULL DEFAULT ('menu'), `permission` text NULL, `query` text NULL, `is_external` bool NOT NULL DEFAULT (false), `embed` bool NOT NULL DEFAULT (false), `keep_alive` bool NOT NULL DEFAULT (false), `sort` integer NOT NULL DEFAULT (0), `status` text NOT NULL DEFAULT ('enabled'), `visible` bool NOT NULL DEFAULT (true), `feature_key` text NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `menu_name` ON `menus` (`name`);
CREATE TABLE `positions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `code` text NOT NULL, `sort` integer NOT NULL DEFAULT (0), `status` text NOT NULL DEFAULT ('enabled'), `remark` text NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `position_code` ON `positions` (`code`);
CREATE TABLE `roles` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `code` text NOT NULL, `description` text NULL, `status` text NOT NULL DEFAULT ('enabled'), `data_scope` text NOT NULL DEFAULT ('all'), `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `role_code` ON `roles` (`code`);
CREATE TABLE `role_departments` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `role_id` integer NOT NULL, `department_id` integer NOT NULL, CONSTRAINT `role_departments_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE, CONSTRAINT `role_departments_department_id_fk` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `roledepartment_role_id_department_id` ON `role_departments` (`role_id`, `department_id`);
CREATE TABLE `role_menus` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `role_id` integer NOT NULL, `menu_id` integer NOT NULL, CONSTRAINT `role_menus_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE, CONSTRAINT `role_menus_menu_id_fk` FOREIGN KEY (`menu_id`) REFERENCES `menus` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `rolemenu_role_id_menu_id` ON `role_menus` (`role_id`, `menu_id`);
CREATE TABLE `role_permissions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `role_id` integer NOT NULL, `permission` text NOT NULL, CONSTRAINT `role_permissions_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `rolepermission_role_id_permission` ON `role_permissions` (`role_id`, `permission`);
CREATE TABLE `sessions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `token_hash` text NOT NULL, `csrf_hash` text NOT NULL, `expires_at` datetime NOT NULL, `revoked_at` datetime NULL, `ip` text NOT NULL DEFAULT (''), `client` text NOT NULL DEFAULT ('web'), `browser` text NOT NULL DEFAULT (''), `os` text NOT NULL DEFAULT (''), `last_active_at` datetime NOT NULL, `created_at` datetime NOT NULL, CONSTRAINT `sessions_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `sessions_token_hash_key` ON `sessions` (`token_hash`);
CREATE INDEX `session_user_id` ON `sessions` (`user_id`);
CREATE INDEX `session_expires_at` ON `sessions` (`expires_at`);
CREATE TABLE `system_settings` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `module` text NOT NULL, `version` integer NOT NULL, `data` json NOT NULL, `updated_at` datetime NOT NULL);
CREATE UNIQUE INDEX `system_settings_module_key` ON `system_settings` (`module`);
CREATE TABLE `upload_chunks` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `upload_id` text NOT NULL, `chunk_index` integer NOT NULL, `size` integer NOT NULL, `hash` text NOT NULL, CONSTRAINT `upload_chunks_upload_id_fk` FOREIGN KEY (`upload_id`) REFERENCES `upload_sessions` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `uploadchunk_upload_id_chunk_index` ON `upload_chunks` (`upload_id`, `chunk_index`);
CREATE TABLE `upload_sessions` (`id` text NOT NULL, `storage_config_id` integer NOT NULL, `uploader_id` integer NOT NULL, `file_name` text NOT NULL, `file_size` integer NOT NULL, `mime_type` text NULL, `chunk_size` integer NOT NULL, `total_chunks` integer NOT NULL, `visibility` text NOT NULL DEFAULT ('public'), `status` text NOT NULL DEFAULT ('uploading'), `expires_at` datetime NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `upload_sessions_storage_config_id_fk` FOREIGN KEY (`storage_config_id`) REFERENCES `file_storage_configs` (`id`) ON DELETE RESTRICT, CONSTRAINT `upload_sessions_uploader_id_fk` FOREIGN KEY (`uploader_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT);
CREATE INDEX `uploadsession_expires_at` ON `upload_sessions` (`expires_at`);
CREATE INDEX `uploadsession_uploader_id` ON `upload_sessions` (`uploader_id`);
CREATE TABLE `users` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `username` text NOT NULL, `nickname` text NOT NULL, `password_hash` text NOT NULL, `status` text NOT NULL DEFAULT ('enabled'), `avatar` text NULL, `email` text NULL, `phone` text NULL, `gender` text NULL, `birth_date` text NULL, `department_id` integer NULL, `preferences` json NULL, `favorite_menus` json NULL, `user_data_scope` text NULL, `password_updated_at` datetime NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, CONSTRAINT `users_department_id_fk` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL);
CREATE UNIQUE INDEX `user_username` ON `users` (`username`);
CREATE TABLE `user_department_scopes` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `department_id` integer NOT NULL, CONSTRAINT `user_department_scopes_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `user_department_scopes_department_id_fk` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `userdepartmentscope_user_id_department_id` ON `user_department_scopes` (`user_id`, `department_id`);
CREATE TABLE `user_groups` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `code` text NOT NULL, `description` text NULL, `owner_id` integer NULL, `member_mode` text NOT NULL DEFAULT ('static'), `member_rule` json NULL, `rule_synced_at` datetime NULL, `status` text NOT NULL DEFAULT ('enabled'), `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, CONSTRAINT `user_groups_owner_id_fk` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE SET NULL);
CREATE UNIQUE INDEX `usergroup_code` ON `user_groups` (`code`);
CREATE TABLE `user_group_members` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `group_id` integer NOT NULL, `user_id` integer NOT NULL, `created_at` datetime NOT NULL, CONSTRAINT `user_group_members_group_id_fk` FOREIGN KEY (`group_id`) REFERENCES `user_groups` (`id`) ON DELETE CASCADE, CONSTRAINT `user_group_members_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `usergroupmember_group_id_user_id` ON `user_group_members` (`group_id`, `user_id`);
CREATE TABLE `user_group_roles` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `group_id` integer NOT NULL, `role_id` integer NOT NULL, CONSTRAINT `user_group_roles_group_id_fk` FOREIGN KEY (`group_id`) REFERENCES `user_groups` (`id`) ON DELETE CASCADE, CONSTRAINT `user_group_roles_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `usergrouprole_group_id_role_id` ON `user_group_roles` (`group_id`, `role_id`);
CREATE TABLE `user_menus` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `menu_id` integer NOT NULL, CONSTRAINT `user_menus_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `user_menus_menu_id_fk` FOREIGN KEY (`menu_id`) REFERENCES `menus` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `usermenu_user_id_menu_id` ON `user_menus` (`user_id`, `menu_id`);
CREATE TABLE `user_permissions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `permission` text NOT NULL, CONSTRAINT `user_permissions_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `userpermission_user_id_permission` ON `user_permissions` (`user_id`, `permission`);
CREATE TABLE `user_positions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `position_id` integer NOT NULL, `created_at` datetime NOT NULL, CONSTRAINT `user_positions_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `user_positions_position_id_fk` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `userposition_user_id_position_id` ON `user_positions` (`user_id`, `position_id`);
CREATE TABLE `user_roles` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `user_id` integer NOT NULL, `role_id` integer NOT NULL, CONSTRAINT `user_roles_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `user_roles_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `userrole_user_id_role_id` ON `user_roles` (`user_id`, `role_id`);

CREATE UNIQUE INDEX file_storage_configs_default_unique ON file_storage_configs(is_default) WHERE is_default = 1;
